<script lang="ts">
  import { onMount } from "svelte";
  import WritingStudio from "./WritingStudio.svelte";
  import ContentManager from "./ContentManager.svelte";

  type Post = { file: string; title?: string; draft?: boolean; published?: string; description?: string };
  type Sidebar = { enable: boolean; position: "left" | "right" | "both"; leftComponents: Array<Record<string, unknown>>; rightComponents: Array<Record<string, unknown>>; mobileBottomComponents: Array<Record<string, unknown>> };
  type Announcement = { title: string; closable: boolean; items: Array<{ tag: string; title: string; content: string; time: string; link?: string; sort: number }> };

  const AUTH_KEY = "firefly-writing-auth";
  const nav = [
    ["dashboard", "工作台", "⌂"], ["writing", "文章管理", "▤"], ["routines", "规划记录", "□"],
    ["notebooks", "笔记本", "▥"], ["settings", "站点管理", "◇"], ["announcements", "公告管理", "◈"],
  ];
  const componentLabels: Record<string, string> = { profile: "个人资料", announcement: "公告", music: "音乐播放器", categories: "分类", tags: "标签", stats: "站点统计", calendar: "日历", sidebarToc: "文章目录" };
  let password = $state("");
  let token = $state("");
  let authenticated = $state(false);
  let loading = $state(false);
  let message = $state("");
  let posts = $state<Post[]>([]);
  let routines = $state<{ file: string }[]>([]);
  let sidebar = $state<Sidebar | null>(null);
  let announcements = $state<Announcement | null>(null);
  let active = $state("dashboard");
  let accountOpen = $state(false);
  let theme = $state<"dark" | "light" | "system">("dark");
  let settingsDirty = $state(false);
  let mobileOpen = $state(false);

  const api = async (path: string, init: RequestInit = {}) => {
    const response = await fetch(path, { ...init, headers: { "Content-Type": "application/json", "x-writing-auth": token, ...(init.headers || {}) } });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || `请求失败（${response.status}）`);
    return data;
  };
  async function login() {
    if (!password || loading) return;
    loading = true; message = "";
    try {
      const data = await fetch("/api/writing/auth/", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ password }) }).then(async (res) => { const body = await res.json(); if (!res.ok) throw new Error(body.error || "登录失败"); return body; });
      token = data.token; sessionStorage.setItem(AUTH_KEY, token); authenticated = true; password = ""; await load();
    } catch (error) { message = error instanceof Error ? error.message : String(error); }
    finally { loading = false; }
  }
  async function load() {
    loading = true; message = "";
    try {
      const [postData, routineData, sidebarData, announcementData] = await Promise.all([
        api("/api/writing/posts/?_=" + Date.now()), api("/api/writing/content/routines/"), api("/api/writing/content/sidebar/"), api("/api/writing/content/announcements/")
      ]);
      posts = postData.posts || []; routines = routineData.items || [];
      sidebar = JSON.parse(sidebarData.source); announcements = JSON.parse(announcementData.source); settingsDirty = false;
    } catch (error) { message = error instanceof Error ? error.message : String(error); if (/登录已过期/.test(message)) logout(); }
    finally { loading = false; }
  }
  function logout() { sessionStorage.removeItem(AUTH_KEY); token = ""; authenticated = false; accountOpen = false; }
  function setTheme(next: "dark" | "light" | "system") { theme = next; localStorage.setItem("firefly-admin-theme", next); document.documentElement.classList.toggle("dark", next === "dark" || (next === "system" && matchMedia("(prefers-color-scheme: dark)").matches)); }
  function setSidebarValue(side: "leftComponents" | "rightComponents", index: number, enabled: boolean) { if (!sidebar) return; sidebar = { ...sidebar, [side]: sidebar[side].map((item, i) => i === index ? { ...item, enable: enabled } : item) }; settingsDirty = true; }
  function setSideEnabled(side: "leftComponents" | "rightComponents", enabled: boolean) { if (!sidebar) return; sidebar = { ...sidebar, [side]: sidebar[side].map((item) => ({ ...item, enable: enabled })) }; settingsDirty = true; }
  function moveComponent(side: "leftComponents" | "rightComponents", index: number, direction: -1 | 1) { if (!sidebar) return; const next = index + direction; if (next < 0 || next >= sidebar[side].length) return; const items = [...sidebar[side]]; [items[index], items[next]] = [items[next], items[index]]; sidebar = { ...sidebar, [side]: items }; settingsDirty = true; }
  async function saveSidebar() { if (!sidebar) return; loading = true; try { const current = await api("/api/writing/content/sidebar/"); const result = await api("/api/writing/content/sidebar/", { method: "PUT", body: JSON.stringify({ source: JSON.stringify(sidebar, null, 2), version: current.version }) }); message = "设置已保存到仓库，等待部署生效"; settingsDirty = false; void result; } catch (error) { message = error instanceof Error ? error.message : String(error); } finally { loading = false; } }
  async function saveAnnouncements() { if (!announcements) return; loading = true; try { const current = await api("/api/writing/content/announcements/"); await api("/api/writing/content/announcements/", { method: "PUT", body: JSON.stringify({ source: JSON.stringify(announcements, null, 2), version: current.version }) }); message = "公告已保存到仓库，等待部署生效"; settingsDirty = false; } catch (error) { message = error instanceof Error ? error.message : String(error); } finally { loading = false; } }
  function scrollTo(id: string) { active = id; mobileOpen = false; document.getElementById(`admin-${id}`)?.scrollIntoView({ behavior: "smooth", block: "start" }); }
  onMount(() => { token = sessionStorage.getItem(AUTH_KEY) || ""; const stored = localStorage.getItem("firefly-admin-theme") as typeof theme | null; if (stored) theme = stored; setTheme(theme); if (token) { authenticated = true; void load(); } });
</script>

{#if !authenticated}
  <main class="admin-login"><div class="admin-login-card"><div class="admin-mark">◇</div><p class="admin-eyebrow">PERSONAL WORKSPACE</p><h1>博客管理</h1><p class="admin-muted">写下想法，有序记录，持续更新。</p><form onsubmit={(event) => { event.preventDefault(); void login(); }}><label>管理密码<input type="password" bind:value={password} autocomplete="current-password" placeholder="输入管理密码" /></label><button class="admin-primary" disabled={loading || !password}>{loading ? "验证中…" : "进入工作台"}</button></form>{#if message}<p class="admin-error" role="alert">{message}</p>{/if}</div></main>
{:else}
  <div class="admin-shell">
    <aside class:open={mobileOpen} class="admin-sidebar"><div class="admin-brand"><span class="admin-brand-mark">◇</span><span><strong>博客管理</strong><small>PERSONAL WORKSPACE</small></span></div><nav aria-label="后台导航">{#each nav as item}<button class:active={active === item[0]} onclick={() => scrollTo(item[0])}><span class="admin-nav-icon">{item[2]}</span>{item[1]}</button>{/each}</nav><div class="admin-account"><div class="admin-account-line"><button class="admin-account-main" onclick={() => (accountOpen = !accountOpen)}><span class="admin-avatar">管</span><span><strong>管理员</strong><small>个人工作区</small></span><span class="admin-chevron">⌄</span></button><button class="admin-theme-button" aria-label="切换主题" onclick={() => setTheme(theme === "dark" ? "light" : "dark")}>{theme === "dark" ? "☼" : "☾"}</button></div>{#if accountOpen}<div class="admin-account-menu"><button onclick={() => setTheme("dark")}>深色模式</button><button onclick={() => setTheme("light")}>浅色模式</button><button onclick={() => setTheme("system")}>跟随系统</button><button onclick={logout}>退出登录</button></div>{/if}</div></aside>
    {#if mobileOpen}<button class="admin-backdrop" aria-label="关闭菜单" onclick={() => (mobileOpen = false)}></button>{/if}
    <section class="admin-main"><header class="admin-topbar"><button class="admin-menu-button" aria-label="打开导航" onclick={() => (mobileOpen = true)}>☰</button><div class="admin-breadcrumb">控制台 <span>/</span> <strong>{nav.find((item) => item[0] === active)?.[1] || "工作台"}</strong></div><input class="admin-search" aria-label="搜索内容" placeholder="搜索内容…" /><button class="admin-icon-button" aria-label="刷新" onclick={() => void load()}>↻</button></header><div class="admin-content">
      <section id="admin-dashboard" class="admin-section"><div class="admin-heading"><div><p class="admin-eyebrow">OVERVIEW</p><h1>工作台</h1><p class="admin-muted">写下想法，有序记录，持续更新。</p></div><button class="admin-primary" onclick={() => scrollTo("writing")}>＋ 新建文章</button></div><div class="admin-stats"><article><span>文章总数</span><strong>{posts.length}</strong><small>包含已发布与草稿</small></article><article><span>草稿</span><strong>{posts.filter((post) => post.draft).length}</strong><small>等待继续编辑</small></article><article><span>规划进行中</span><strong>{routines.length}</strong><small>来自规划记录</small></article></div><div class="admin-grid"><div class="admin-panel admin-recent"><div class="admin-panel-heading"><h2>最近编辑</h2><button class="admin-link" onclick={() => scrollTo("writing")}>查看全部 →</button></div>{#if posts.length}<div class="admin-table-head"><span>标题</span><span>类型</span><span>状态</span><span>更新时间</span></div>{#each posts.slice(0, 6) as post}<button class="admin-row" onclick={() => scrollTo("writing")}><span>{post.title || post.file}</span><span>文章</span><span class:published={!post.draft} class="admin-status">{post.draft ? "草稿" : "已发布"}</span><span>{post.published || "—"}</span><b>•••</b></button>{/each}{:else}<div class="admin-empty">还没有文章，点击右上角开始写作。</div>{/if}</div><aside class="admin-side-stack"><div class="admin-panel"><div class="admin-panel-heading"><h2>组件快捷设置</h2><span class="admin-hint">保存后重构建生效</span></div>{#if sidebar}<label class="admin-setting-row"><span>左侧栏</span><input type="checkbox" checked={sidebar.leftComponents.some((item) => item.enable)} onchange={(event) => setSideEnabled("leftComponents", (event.currentTarget as HTMLInputElement).checked)} /></label><label class="admin-setting-row"><span>右侧栏</span><input type="checkbox" checked={sidebar.rightComponents.some((item) => item.enable)} onchange={(event) => setSideEnabled("rightComponents", (event.currentTarget as HTMLInputElement).checked)} /></label>{#each sidebar.leftComponents.slice(0, 3) as item, i}<label class="admin-setting-row nested"><span>{componentLabels[String(item.type)] || item.type}</span><input type="checkbox" checked={Boolean(item.enable)} onchange={(event) => setSidebarValue("leftComponents", i, (event.currentTarget as HTMLInputElement).checked)} /></label>{/each}<button class="admin-link" onclick={() => scrollTo("settings")}>进入组件管理 →</button>{/if}</div><div class="admin-panel"><div class="admin-panel-heading"><h2>当前公告</h2><span class="admin-badge">{announcements?.items?.[0]?.tag || "—"}</span></div><h3>{announcements?.items?.[0]?.title || "暂无公告"}</h3><p class="admin-muted">{announcements?.items?.[0]?.content || "可以在公告管理中添加一条公告。"}</p><button class="admin-secondary" onclick={() => scrollTo("announcements")}>编辑公告</button></div></aside></div><div class="admin-panel admin-resume"><div><p class="admin-eyebrow">CONTINUE</p><h2>{posts.find((post) => post.draft)?.title || "开始新的写作"}</h2><p class="admin-muted">{posts.find((post) => post.draft)?.description || "把复杂的事情拆解成一个可执行的小步骤，时间会给出最好的答案。"}</p></div><button class="admin-secondary" onclick={() => scrollTo("writing")}>继续编辑 →</button></div></section>
      <section id="admin-writing" class="admin-section admin-tools"><div class="admin-section-title"><div><p class="admin-eyebrow">CONTENT</p><h2>文章管理</h2></div><button class="admin-link" onclick={() => scrollTo("dashboard")}>返回工作台 ↑</button></div><WritingStudio /></section><section id="admin-routines" class="admin-section admin-tools"><div class="admin-section-title"><div><p class="admin-eyebrow">LIFE LOG</p><h2>规划记录与笔记本</h2><p class="admin-muted">使用 Markdown 与实时预览编辑生活记录。</p></div></div><ContentManager /></section>
      <section id="admin-settings" class="admin-section admin-tools"><div class="admin-section-title"><div><p class="admin-eyebrow">LAYOUT</p><h2>组件管理</h2><p class="admin-muted">左下角仅保留一个管理员入口和主题切换，顶部不再重复显示。</p></div><div class="admin-actions">{#if settingsDirty}<span class="admin-unsaved">未保存</span>{/if}<button class="admin-secondary" onclick={() => void load()}>取消修改</button><button class="admin-primary small" disabled={!settingsDirty || loading} onclick={() => void saveSidebar()}>保存设置</button></div></div><div class="admin-settings-grid">{#each [["leftComponents", "左侧栏"], ["rightComponents", "右侧栏"]] as group}<div class="admin-panel"><h3>{group[1]}</h3>{#if sidebar}{#each sidebar[group[0] as "leftComponents" | "rightComponents"] as item, i}<div class="admin-component-row"><span class="admin-drag">⋮⋮</span><span>{componentLabels[String(item.type)] || item.type}<small>{item.position === "top" ? "顶部" : "吸附"}</small></span><button class="admin-order-button" aria-label="上移" onclick={() => moveComponent(group[0] as "leftComponents" | "rightComponents", i, -1)}>↑</button><button class="admin-order-button" aria-label="下移" onclick={() => moveComponent(group[0] as "leftComponents" | "rightComponents", i, 1)}>↓</button><input type="checkbox" checked={Boolean(item.enable)} onchange={(event) => setSidebarValue(group[0] as "leftComponents" | "rightComponents", i, (event.currentTarget as HTMLInputElement).checked)} /></div>{/each}{/if}</div>{/each}</div></section>
      <section id="admin-announcements" class="admin-section admin-tools"><div class="admin-section-title"><div><p class="admin-eyebrow">BROADCAST</p><h2>公告管理</h2><p class="admin-muted">停用公告会从所有展示位置同步隐藏。</p></div><div class="admin-actions">{#if announcements}<button class="admin-primary small" disabled={loading} onclick={() => void saveAnnouncements()}>保存公告</button>{/if}</div></div>{#if announcements}<div class="admin-panel admin-announcement-editor"><label>公告栏标题<input bind:value={announcements.title} oninput={() => (settingsDirty = true)} /></label><label class="admin-check"><input type="checkbox" bind:checked={announcements.closable} onchange={() => (settingsDirty = true)} />允许访客关闭公告栏</label>{#each announcements.items as item}<article class="admin-announcement-item"><div class="admin-fields"><label>标签<input bind:value={item.tag} oninput={() => (settingsDirty = true)} /></label><label>标题<input bind:value={item.title} oninput={() => (settingsDirty = true)} /></label><label>日期<input type="date" bind:value={item.time} oninput={() => (settingsDirty = true)} /></label><label>链接<input bind:value={item.link} placeholder="/about/ 或 https://…" oninput={() => (settingsDirty = true)} /></label></div><label>正文<textarea rows="3" bind:value={item.content} oninput={() => (settingsDirty = true)}></textarea></label></article>{/each}</div>{/if}</section>
      {#if message}<p class="admin-toast" role="status">{message}</p>{/if}
    </div></section>
  </div>
{/if}

<style>
  :global(#top-row), :global(.mobile-dock), :global(.floating-dock), :global(#main-grid-wrapper) { display: none !important; }
  :global(body) { background: #101216; color: #eceff4; }
  :global(html:not(.dark) body) { background: #f5f7fa; color: #17202b; }
  :global(html:not(.dark)) .admin-shell { --a-bg:#f5f7fa; --a-panel:#ffffff; --a-border:#dbe1e8; --a-text:#18212b; --a-muted:#647184; --a-accent:#4d8cc7; }
  :global(html:not(.dark)) .admin-sidebar { background:#eef2f6; }
  :global(html:not(.dark)) .admin-topbar { background:#f5f7faee; }
  :global(html:not(.dark)) .admin-search, :global(html:not(.dark)) .admin-announcement-editor input, :global(html:not(.dark)) .admin-announcement-editor textarea { background:#fff; }
  :global(body:has(.admin-shell)) { min-width: 320px; }
  .admin-shell { --a-bg:#101216; --a-panel:#191c22; --a-border:#2b3038; --a-text:#eceff4; --a-muted:#9aa4b2; --a-accent:#88bbee; min-height:100vh; display:flex; background:var(--a-bg); color:var(--a-text); }
  .admin-sidebar { width:232px; flex:0 0 232px; min-height:100vh; border-right:1px solid var(--a-border); display:flex; flex-direction:column; padding:25px 14px 18px; position:sticky; top:0; height:100vh; z-index:20; background:#12151a; }
  .admin-brand { display:flex; align-items:center; gap:10px; padding:0 8px 30px; }.admin-brand-mark,.admin-mark { width:34px;height:34px;display:grid;place-items:center;border:1px solid var(--a-accent);border-radius:10px;color:var(--a-accent);font-size:22px; }.admin-brand strong{display:block;font-size:16px}.admin-brand small,.admin-account small{display:block;color:var(--a-muted);font:10px ui-monospace,monospace;letter-spacing:.06em;margin-top:3px}
  .admin-sidebar nav{display:grid;gap:5px}.admin-sidebar nav button{border:0;background:transparent;color:var(--a-muted);display:flex;align-items:center;gap:13px;padding:11px 12px;border-radius:7px;text-align:left;font-size:14px;cursor:pointer;transition:all .18s}.admin-sidebar nav button:hover,.admin-sidebar nav button.active{background:#263d5b;color:#dceeff}.admin-nav-icon{width:18px;text-align:center;color:var(--a-accent);font-size:18px}.admin-account{margin-top:auto;border-top:1px solid var(--a-border);padding-top:15px;position:relative}.admin-account-line{display:flex;align-items:center;gap:5px}.admin-account-main{width:100%;border:0;background:transparent;color:var(--a-text);display:flex;align-items:center;gap:10px;text-align:left;padding:5px;cursor:pointer}.admin-avatar{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(145deg,#526e8e,#202631);border:1px solid #9cc6eb;color:white}.admin-account-main strong{font-size:13px}.admin-theme-button{width:32px;height:32px;border:1px solid var(--a-border);border-radius:7px;background:transparent;color:var(--a-muted);cursor:pointer;font-size:17px}.admin-theme-button:hover{border-color:var(--a-accent);color:var(--a-accent)}.admin-chevron{margin-left:auto;color:var(--a-muted)}.admin-account-menu{position:absolute;bottom:58px;left:0;right:0;background:var(--a-panel);border:1px solid var(--a-border);border-radius:9px;padding:5px;box-shadow:0 12px 30px #0008}.admin-account-menu button{display:block;width:100%;border:0;background:transparent;color:var(--a-text);padding:8px;text-align:left;border-radius:6px;cursor:pointer}.admin-account-menu button:hover{background:#263d5b}.admin-main{flex:1;min-width:0}.admin-topbar{height:66px;border-bottom:1px solid var(--a-border);display:flex;align-items:center;gap:18px;padding:0 34px;position:sticky;top:0;background:#101216ee;backdrop-filter:blur(12px);z-index:10}.admin-breadcrumb{font-size:14px;color:var(--a-muted)}.admin-breadcrumb span{